    tk = get_ticket(t)
    if tk['priority'] == 'high':
        cid = tk['customer_id']
        if cid not in seen:
            seen[cid] = True
            cust = get_customer(cid)
            if cust['tier'] == 'gold':
                gold_ids.append(cid)
